-- Documents bounded context core tables (P5.6): document_category, document,
-- audit_log. Owner references are Keycloak subjects (UUIDs, no cross-service
-- FK, §2.4); the category FK is intra-schema and enforced.
-- Must run on PostgreSQL (compose) AND H2 in PostgreSQL mode (local/tests):
-- stick to the common SQL subset — UUIDs are generated by the application.

create table document_category (
    id          uuid primary key,
    name        varchar(100) not null unique,
    description varchar(500),
    -- minimum role required to read documents in this category (FR-41);
    -- HR/ADMIN tiers are "sensitive"
    min_role    varchar(20)  not null,
    created_at  timestamp with time zone not null,
    updated_at  timestamp with time zone not null,
    constraint ck_document_category_min_role check (min_role in ('EMPLOYEE', 'MANAGER', 'HR', 'ADMIN'))
);

create table document (
    id                 uuid primary key,
    title              varchar(200) not null,
    description        varchar(500),
    category_id        uuid         not null,
    -- keycloak subject of the owning employee; null = company-wide
    owner_keycloak_id  uuid,
    -- pointer to the blob in volume-backed storage (metadata service holds no bytes)
    storage_key        varchar(500) not null,
    content_type       varchar(100),
    size_bytes         bigint,
    uploaded_by        varchar(255) not null,
    created_at         timestamp with time zone not null,
    updated_at         timestamp with time zone not null,
    constraint fk_document_category foreign key (category_id) references document_category (id)
);

create index ix_document_category on document (category_id);
create index ix_document_owner    on document (owner_keycloak_id);

-- Seed the default access tiers so uploads have categories to reference.
insert into document_category (id, name, description, min_role, created_at, updated_at) values
    ('cccccccc-0000-0000-0000-000000000001', 'General',
        'Company-wide documents readable by any employee', 'EMPLOYEE', now(), now()),
    ('cccccccc-0000-0000-0000-000000000002', 'HR Confidential',
        'Sensitive HR documents — HR and Admin only', 'HR', now(), now()),
    ('cccccccc-0000-0000-0000-000000000003', 'Payroll',
        'Payroll documents — Admin only', 'ADMIN', now(), now());

-- Append-only audit trail: rows are only ever inserted. On PostgreSQL the
-- schema grants deny UPDATE/DELETE to the service role; H2 (dev/tests) relies
-- on the code path never issuing them.
create table audit_log (
    id          uuid         primary key,
    actor       varchar(255) not null,
    action      varchar(100) not null,
    resource    varchar(255) not null,
    details     varchar(2000),
    occurred_at timestamp with time zone not null
);

create index ix_audit_log_resource on audit_log (resource);
create index ix_audit_log_action   on audit_log (action);
